 {data&&<section className="panel mt-6"><div className="section-heading"><div><h2>{data.campus.name} · Payroll {data.run.period.slice(0,7)}</h2><p className="muted">{data.run.status==='approved'?`Approved ${data.run.approved_at?pkt(data.run.approved_at):''} PKT`:'Draft — review and approve before paying salary.'}</p></div><span className={'pay-state '+data.run.status}>{label(data.run.status)}</span></div>{data.run.snapshot&&<MoneySummary totals={data.run.snapshot.totals}/>}<div className="pay-run-items">{data.items.map(i=><article key={i.id}><div><strong>{i.snapshot?.name??`Staff #${i.staff_profile_id}`}</strong><small>{i.snapshot?.employee_no} · Original net PKR {money(i.net_amount)}</small>{i.totals&&<p><span>Paid PKR {money(i.totals.paid)}</span><strong>Outstanding PKR {money(i.totals.balance)}</strong></p>}</div>{data.run.status==='approved'&&<button className="secondary" onClick={()=>setSlip(i.id)}>Open payslip {i.snapshot?.employee_no}</button>}</article>)}</div><div className="pay-actions mt-5">{data.run.status==='draft'&&setup.can_approve&&<button className="primary" disabled={a.busy} onClick={()=>setApproval(true)}>Approve monthly payroll</button>}<button className="secondary" onClick={()=>setHistoryOpen(!historyOpen)}><History size={16}/>{historyOpen?'Hide payroll history':'View payroll history'}</button></div>{historyOpen&&<RunHistory run={data.run}/>}</section>}
