function ActionDialog({title,busy,onCancel,button,onConfirm,disabled,children}:{title:string;busy:boolean;onCancel:()=>void;button:string;onConfirm:()=>void;disabled?:boolean;children:ReactNode}){const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{ref.current?.showModal();},[]);return <dialog ref={ref} className="pay-dialog" onCancel={e=>{e.preventDefault();if(!busy)onCancel();}}><form onSubmit={e=>{e.preventDefault();onConfirm();}}><h2>{title}</h2>{children}<div className="pay-actions mt-5"><button type="button" className="secondary" disabled={busy} onClick={onCancel}>Cancel</button><button className="primary" disabled={busy||disabled}>{busy?'Saving…':button}</button></div></form></dialog>;}
function RunHistory({run}:{run:Run}){const [page,setPage]=useState(1),[data,setData]=useState<{data:{id:number;action:string;actor_name:string;occurred_at:string}[];last_page:number}|null>(null),[error,setError]=useState('');useEffect(()=>{api<typeof data>(`/payroll/runs/${run.id}/history?page=${page}`).then(setData).catch(e=>setError(e.message));},[run.id,page]);return <div className="pay-history"><Notice error={error} message=""/>{data?.data.map(x=><p key={x.id}><strong>{label(x.action.replace('payroll.',''))}</strong> · {x.actor_name??'System'}<small>{pkt(x.occurred_at)} PKT</small></p>)}<div className="pay-actions"><button className="secondary" disabled={page===1} onClick={()=>setPage(page-1)}>Previous audit</button><button className="secondary" disabled={!data||page>=data.last_page} onClick={()=>setPage(page+1)}>Next audit</button></div></div>;}
function SelfPortal({setup}:{setup:Setup}){const [data,setData]=useState<{staff:Staff|null;payslips:{id:number;net_amount:string;period:string}[]}|null>(null),[error,setError]=useState(''),[slip,setSlip]=useState<number|null>(null);useEffect(()=>{api<typeof data>('/payroll/self').then(setData).catch(e=>setError(e.message));},[]);return <><Notice error={error} message=""/><section className="panel"><h2>My approved payslips</h2>{data&&!data.staff&&<p className="muted">Your school has not linked a staff profile to this account yet.</p>}<div className="pay-run-items">{data?.payslips.map(i=><article key={i.id}><div><strong>{i.period.slice(0,7)}</strong><small>Original net PKR {money(i.net_amount)}</small></div><button className="secondary" onClick={()=>setSlip(i.id)}>View my payslip {i.period.slice(0,7)}</button></article>)}</div>{data?.staff&&!data.payslips.length&&<p className="muted">No approved payslips yet.</p>}</section>{slip&&<SlipView key={slip} id={slip} setup={setup}/>} {data?.staff&&<Leaves setup={setup} selfStaff={data.staff}/>}</>;}
function SlipView({id,setup,onChanged}:{id:number;setup:Setup;onChanged?:()=>Promise<void>}){const a=useAction(),[s,setS]=useState<Slip|null>(null),[amount,setAmount]=useState(''),[paidOn,setPaidOn]=useState(setup.today),[method,setMethod]=useState('cash'),[bank,setBank]=useState(''),[reference,setReference]=useState(''),[key,setKey]=useState(crypto.randomUUID()),[kind,setKind]=useState('credit'),[adjustAmount,setAdjustAmount]=useState(''),[reason,setReason]=useState(''),[recovery,setRecovery]=useState(''),[confirmPay,setConfirmPay]=useState(false),[review,setReview]=useState<{type:'reverse'|'approve'|'reject';id:number}|null>(null),[reviewReason,setReviewReason]=useState(''),[paper,setPaper]=useState<ReactNode|null>(null);async function refresh(){setS(await api<Slip>(`/payroll/items/${id}/payslip`));await onChanged?.();}useEffect(()=>{void refresh().catch(e=>a.setError(e.message));},[id]);if(!s)return <section className="panel mt-6"><Notice error={a.error} message=""/>Loading payslip…</section>;const snap=s.item.snapshot!;return <section className="panel mt-6 pay-slip"><Notice error={a.error} message={a.message}/><div className="section-heading"><div><h2>Payslip · {snap.name}</h2><p className="muted">{snap.employee_no} · {s.run.period.slice(0,7)} · {snap.campus_name}</p></div><button className="secondary" onClick={()=>setPaper(<PayslipContent slip={s}/>)}><Printer size={16}/>Print payslip</button></div><MoneySummary totals={{gross:s.item.gross_amount,deductions:s.item.deduction_amount,recoveries:s.item.advance_recovery,net:s.item.net_amount}}/><div className="pay-money-grid"><span>Approved credits<strong>{money(s.totals.credits)}</strong></span><span>Approved debits<strong>{money(s.totals.debits)}</strong></span><span>Current payable<strong>{money(s.totals.payable)}</strong></span><span>Net paid<strong>{money(s.totals.paid)}</strong></span><span>Outstanding PKR<strong>{money(s.totals.balance)}</strong></span></div><div className="table-scroll"><table><thead><tr><th>Original component</th><th>Kind</th><th>PKR</th></tr></thead><tbody>{snap.components.map((c,i)=><tr key={i}><td>{c.name}</td><td>{label(c.kind)}</td><td>{money(c.amount)}</td></tr>)}</tbody></table></div>
{s.can_manage&&Number(s.totals.balance)>0&&<form className="pay-subform" onSubmit={e=>{e.preventDefault();setConfirmPay(true);}}><h3>Record salary payment</h3><div className="form-grid"><Field name="Salary amount PKR *"><input aria-label="Salary payment amount" required type="number" min="0.01" max={s.totals.balance} step="0.01" value={amount} onChange={e=>setAmount(e.target.value)}/></Field><Field name="Salary payment date *"><input aria-label="Salary payment date" required type="date" min={s.run.period} max={setup.today} value={paidOn} onChange={e=>setPaidOn(e.target.value)}/></Field><BankFields setup={setup} campus={s.run.campus_id} method={method} bank={bank} onMethod={setMethod} onBank={setBank}/><Field name="Payment reference"><input aria-label="Salary payment reference" maxLength={160} value={reference} onChange={e=>setReference(e.target.value)}/></Field></div><div className="pay-actions"><button className="secondary" type="button" onClick={()=>setAmount(s.totals.balance)}>Use outstanding amount</button><button className="primary" disabled={a.busy}>Review salary payment</button></div></form>}
<h3 className="mt-6">Payment history</h3><div className="pay-appointments">{s.payments.map(p=><article key={p.id}><div><strong>PKR {money(p.allocated)} · {label(p.method)}</strong><small>{p.paid_at.slice(0,10)} · {p.reference??'No reference'}</small>{p.reversed_at&&<p className="error-box">Reversed: {p.reversal_reason}</p>}</div><div className="pay-actions"><button className="secondary" onClick={()=>void a.act(async()=>{const r=await api<Receipt>(`/payroll/payments/${p.id}/receipt`);setPaper(<ReceiptContent receipt={r}/>);})}>Salary receipt #{p.id}</button>{!p.reversed_at&&s.can_approve&&<button className="secondary" onClick={()=>{setReview({type:'reverse',id:p.id});setReviewReason('');}}>Reverse payment #{p.id}</button>}</div></article>)}</div>{!s.payments.length&&<p className="muted">No salary payments recorded.</p>}
{s.can_manage&&<form className="pay-subform" onSubmit={e=>{e.preventDefault();void a.act(async()=>{const d=await api<{message:string}>('/payroll/adjustments','POST',{payroll_item_id:id,kind,amount:adjustAmount,advance_recovery_id:kind==='recovery_refund'?Number(recovery):null,reason});await refresh();setReason('');setAdjustAmount('');return d;});}}><h3>Request an adjustment</h3><p className="muted">Original salary stays frozen. Only approved adjustments change the payable balance.</p><div className="form-grid"><Field name="Adjustment kind *"><select aria-label="Salary adjustment kind" value={kind} onChange={e=>setKind(e.target.value)}><option value="credit">Credit / extra payable</option><option value="debit">Debit / reduce payable</option><option value="recovery_refund">Restore advance recovery</option></select></Field><Field name="Adjustment PKR *"><input aria-label="Salary adjustment amount" required type="number" min="0.01" max="99999999.99" step="0.01" value={adjustAmount} onChange={e=>setAdjustAmount(e.target.value)}/></Field>{kind==='recovery_refund'&&<Field name="Original recovery *"><select required value={recovery} onChange={e=>setRecovery(e.target.value)}><option value="">Choose booked recovery</option>{s.recoveries.map(r=><option key={r.id} value={r.id}>Advance #{r.staff_advance_id} · PKR {money(r.amount)}</option>)}</select></Field>}</div><Field name="Adjustment reason *"><textarea aria-label="Salary adjustment reason" required minLength={5} maxLength={2000} value={reason} onChange={e=>setReason(e.target.value)}/></Field><button className="primary" disabled={a.busy}>Request salary adjustment</button></form>}
<h3 className="mt-6">Adjustment history</h3>{s.adjustments.map(j=><article className="pay-adjustment" key={j.id}><strong>{label(j.kind)} · PKR {money(j.amount)} · {label(j.status)}</strong><p>{j.reason}</p>{j.status==='requested'&&s.can_approve&&<div className="pay-actions">{(['approve','reject'] as const).map(type=><button key={type} className="secondary" onClick={()=>{setReview({type,id:j.id});setReviewReason('');}}>{label(type)} adjustment #{j.id}</button>)}</div>}</article>)}{!s.adjustments.length&&<p className="muted">No adjustments requested.</p>}
{confirmPay&&<ActionDialog title="Confirm salary payment" busy={a.busy} onCancel={()=>setConfirmPay(false)} button="Confirm salary payment" onConfirm={()=>void a.act(async()=>{const d=await api<{message:string}>('/payroll/payments','POST',{campus_id:s.run.campus_id,staff_profile_id:s.item.staff_profile_id,amount,paid_on:paidOn,method,bank_account_id:bank?Number(bank):null,reference:reference||null,idempotency_key:key,allocations:[{payroll_item_id:id,amount}]});setConfirmPay(false);setKey(crypto.randomUUID());setAmount('');await refresh();return d;})}><p>{snap.name} · {paidOn} · {label(method)}</p><p><strong>PKR {money(amount)}</strong></p><p className="muted">This records your payment and does not transfer funds.</p></ActionDialog>}
{review&&<ActionDialog title={review.type==='reverse'?'Reverse salary payment?':`${label(review.type)} salary adjustment?`} busy={a.busy} onCancel={()=>setReview(null)} button="Confirm reviewed correction" onConfirm={()=>void a.act(async()=>{const d=await api<{message:string}>(review.type==='reverse'?`/payroll/payments/${review.id}/reverse`:`/payroll/adjustments/${review.id}/review`,'POST',{action:review.type,reason:reviewReason});setReview(null);await refresh();return d;})}><Field name="Review reason *"><textarea aria-label="Salary correction review reason" required minLength={5} maxLength={1000} value={reviewReason} onChange={e=>setReviewReason(e.target.value)}/></Field><p className="muted">The original transaction remains in history.</p></ActionDialog>}{paper&&<PayPaper onClose={()=>setPaper(null)}>{paper}</PayPaper>}</section>;}
function PayslipContent({slip:s}:{slip:Slip}){const v=s.item.snapshot!;return <><header><p>APPROVED STAFF PAYSLIP · #{s.item.id}</p><h1>{v.school_name}</h1><p>{v.school_code} · {v.campus_name} · {s.run.period.slice(0,7)}</p></header><h2>{v.name} · {v.employee_no}</h2><p>{v.designation??'Staff'} · Approved {s.run.approved_at?pkt(s.run.approved_at)+' PKT':''}</p><table><thead><tr><th>Original component</th><th>Kind</th><th>PKR</th></tr></thead><tbody>{v.components.map((c,i)=><tr key={i}><td>{c.name}</td><td>{label(c.kind)}</td><td>{money(c.amount)}</td></tr>)}</tbody></table><MoneySummary totals={{gross:s.item.gross_amount,deductions:s.item.deduction_amount,recoveries:s.item.advance_recovery,net:s.item.net_amount}}/><h3>Approved adjustments</h3>{s.adjustments.filter(j=>j.status==='approved').map(j=><p key={j.id}>{label(j.kind)} · {money(j.amount)} · {j.reason}</p>)}<p>Credits: {money(s.totals.credits)} · Debits: {money(s.totals.debits)}</p><h3>Current payable PKR {money(s.totals.payable)}</h3><p>Net paid: {money(s.totals.paid)} · Outstanding: {money(s.totals.balance)}</p><h3>Payments</h3>{s.payments.map(p=><p key={p.id}>#{p.id} · {p.paid_at.slice(0,10)} · {label(p.method)} · PKR {money(p.allocated)} {p.reversed_at?'(REVERSED: '+p.reversal_reason+')':''}</p>)}<footer>Original salary calculation is frozen. Balance reflects recorded payments and approved adjustments at print time. Payroll policy version {v.policy_version}. All amounts in PKR.</footer></>;}
function ReceiptContent({receipt:r}:{receipt:Receipt}){const s=r.payment.snapshot;return <><header><p>SALARY PAYMENT RECEIPT · #{r.payment.id}</p><h1>{s.school_name}</h1><p>{s.school_code}</p></header>{r.reversal&&<h2>REVERSED · {r.reversal.reason}</h2>}<h2>{s.staff_name} · {s.employee_no}</h2><p>{r.payment.paid_at.slice(0,10)} · {label(r.payment.method)} · {r.payment.reference??'No reference'}</p><table><thead><tr><th>Payroll period</th><th>Paid PKR</th></tr></thead><tbody>{s.lines.map((l,i)=><tr key={i}><td>{l.period.slice(0,7)}</td><td>{money(l.amount)}</td></tr>)}</tbody></table><h2>Total PKR {money(r.payment.amount)}</h2><footer>This receipt records a salary payment. Reversals preserve the original payment details.</footer></>;}
function PayPaper({children,onClose}:{children:ReactNode;onClose:()=>void}){const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{ref.current?.showModal();const style=document.createElement('style');style.textContent='@media print{@page{size:A4;margin:12mm}}';document.head.append(style);return()=>style.remove();},[]);return <dialog ref={ref} className="pay-paper-overlay" onCancel={e=>{e.preventDefault();onClose();}}><div className="pay-paper-tools"><button className="primary" onClick={()=>window.print()}><Printer size={16}/>Print / Save PDF</button><button className="secondary" onClick={onClose}>Close print preview</button></div><article className="pay-paper">{children}</article></dialog>;}
